import { h } from 'vue';
import { NTag } from 'naive-ui';
import type { TagProps } from 'naive-ui';
import type { CustomNodeData, NodeStatus } from './types';

// 节点状态配置结构（包含文案/颜色/图标 base64）
interface NodeStatusConfig {
  // 状态名称文案
  type: string;
  // 主色（用于图例与图标）
  color: string;
  // Tag 文本颜色
  textColor: string;
  // 圆点图标 base64（普通节点）
  base64: string;
  // 旗帜图标 base64（里程碑节点）
  flag64: string;
  // NodeStatusConfig 接口定义结束
}

// 节点状态映射表（用于图例、tooltip 与节点图标生成）
export const nodeStatus: Record<NodeStatus, NodeStatusConfig> = {
  MILESTONE: {
    type: '里程碑',
    color: '#5b5b5b',
    textColor: '',
    base64: '',
    flag64: ''
  },
  NOT_STARTED: {
    type: '未开始',
    color: '#CCCDD0',
    textColor: '#5b5b5b',
    base64: `data:image/svg+xml;base64,`,
    flag64: `data:image/svg+xml;base64,`
  },
  DELAYED: {
    type: '已延期',
    color: '#B81111',
    textColor: '#dccbcb',
    base64: `data:image/svg+xml;base64,`,
    flag64: `data:image/svg+xml;base64,`
  },
  PAUSED: {
    type: '已暂停',
    color: '#0E42D2',
    textColor: '#dae0f0',
    base64: `data:image/svg+xml;base64,`,
    flag64: `data:image/svg+xml;base64,`
  },
  IN_PROGRESS: {
    type: '进行中',
    color: '#E1BE0D',
    textColor: '#4f4304',
    base64: `data:image/svg+xml;base64,`,
    flag64: `data:image/svg+xml;base64,`
  },
  COMPLETED: {
    type: '已完成',
    color: '#33C73D',
    textColor: '#084e0c',
    base64: `data:image/svg+xml;base64,`,
    flag64: `data:image/svg+xml;base64,`
  },
  COMPLETED_EARLY: {
    type: '提前完成',
    color: '#CCFF99',
    textColor: '#42681d',
    base64: `data:image/svg+xml;base64,`,
    flag64: `data:image/svg+xml;base64,`
  },
  COMPLETED_LATE: {
    type: '延期完成',
    color: '#CC6699',
    textColor: '#4b092a',
    base64: `data:image/svg+xml;base64,`,
    flag64: `data:image/svg+xml;base64,`
  }
};

// 获取节点图标（里程碑使用 flag64，其它使用 base64）
export function getNodeIcon(node: CustomNodeData) {
  // 无状态时返回空字符串
  if (!node.status) return '';

  // 里程碑节点用旗帜图标，否则用圆点图标
  const type = node.milestone ? 'flag64' : 'base64';

  // 返回对应状态的图标
  return nodeStatus[node.status][type];
}

// 获取节点状态 Tag（用于在表格/列表中渲染状态标签）
export function getNodeStatusTag(state: NodeStatus, tagProperty?: TagProps) {
  // 解构状态配置
  const { textColor, color, type } = nodeStatus[state] || {};

  // 返回 NTag 的 VNode
  return h(
    NTag,
    {
      color: { textColor, color },
      bordered: false,
      size: 'small',
      ...tagProperty
    },
    {
      default: () => type
    }
  );
}
